describe('Video Captions Accessibility', () => {
  beforeEach(() => {
    cy.visit('/video-player');
  });

  it('should display captions when video is playing', () => {
    // Verify video element exists
    cy.get('[data-testid="video-player"]').should('be.visible');

    // Verify captions container exists
    cy.get('[data-testid="captions-container"]').should('be.visible');

    // Play the video
    cy.get('[data-testid="play-button"]').click();

    // Wait for video to start playing
    cy.get('[data-testid="video-player"]').should('have.attr', 'src');

    // Verify captions are visible and contain text
    cy.get('[data-testid="captions-container"]').should('be.visible');
    cy.get('[data-testid="caption-text"]').should('contain', 'This is a sample video');

    // Verify captions are styled correctly (e.g, background color)
    cy.get('[data-testid="captions-container"]').should('have.css', 'background-color');

    // Verify captions are not empty
    cy.get('[data-testid="caption-text"]').should('not.have.css', 'display: none');
  });

  it('should hide captions when video is paused or captions are disabled', () => {
    // Play the video to show captions
    cy.get('[data-testid="play-button"]').click();
    cy.get('[data-testid="captions-container"]').should('be.visible');

    // Pause the video
    cy.get('[data-testid="pause-button"]').click();

    // Verify captions are still visible when paused
    cy.get('[data-testid="captions-container"]').should('be.visible');
    cy.get('[data-testid="caption-text"]').should('contain', 'This is a sample video');

    // Disable captions via settings
    cy.get('[data-testid="settings-button"]').click();
    cy.get('[data-testid="caption-toggle"]').click();

    // Verify captions are hidden when disabled
    cy.get('[data-testid="captions-container"]').should('not.exist');

    // Re-enable captions
    cy.get('[data-testid="settings-button"]').click();
    cy.get('[data-testid="caption-toggle"]').click();

    // Verify captions reappear
    cy.get('[data-testid="captions-container"]').should('be.visible');
    cy.get('[data-testid="caption-text"]').should('contain', 'This is a sample video');
  });
});
